#include <iostream>
#include <vector>
using namespace std;

vector<int> pre, in, post;

// 递归重建：pl/pr 前序区间，il/ir 中序区间
void build(int pl, int pr, int il, int ir) {
  if (pl > pr) return;            // 空子树直接返回
  int root = pre[pl];             // 前序第一个是当前根
  int k = il;
  while (in[k] != root) k++;      // 在中序里找到根的位置
  int left = k - il;              // 左子树节点个数
  build(pl + 1, pl + left, il, k - 1);          // 先递归左子树
  build(pl + left + 1, pr, k + 1, ir);          // 再递归右子树
  post.push_back(root);           // 后序：左右都处理完再压根
}

int main() {
  int n; cin >> n;
  pre.resize(n); in.resize(n);
  for (int i = 0; i < n; i++) cin >> pre[i];
  for (int i = 0; i < n; i++) cin >> in[i];
  build(0, n - 1, 0, n - 1);
  for (int i = 0; i < n; i++) {
    if (i) cout << ' ';
    cout << post[i];
  }
  cout << endl;
  return 0;
}

