const int INF = 1e9;

int main() {
  int n, m, c1, c2; cin >> n >> m >> c1 >> c2;
  vector<int> team(n);
  for (int i = 0; i < n; i++) cin >> team[i];
  vector<vector<pair<int,int>>> g(n);   // 邻接表 (to, w)
  for (int i = 0; i < m; i++) {
    int a, b, w; cin >> a >> b >> w;
    g[a].push_back({b, w}); g[b].push_back({a, w});
  }
  vector<int> dist(n, INF), ways(n, 0), teams(n, 0);
  dist[c1] = 0; ways[c1] = 1; teams[c1] = team[c1];
  priority_queue<pair<int,int>, vector<pair<int,int>>, greater<>> pq;
  pq.push({0, c1});
  while (!pq.empty()) {
    auto [d, u] = pq.top(); pq.pop();
    if (d > dist[u]) continue;           // 过期堆元素跳过
    for (auto [v, w] : g[u]) {
      if (dist[v] > dist[u] + w) {       // 找到更短路径：整体更新
        dist[v] = dist[u] + w;
        ways[v] = ways[u];
        teams[v] = teams[u] + team[v];
        pq.push({dist[v], v});
      } else if (dist[v] == dist[u] + w) { // 等长路径：叠加条数、择优救援队
        ways[v] += ways[u];
        teams[v] = max(teams[v], teams[u] + team[v]);
      }
    }
  }
  cout << ways[c2] << ' ' << teams[c2] << endl;
  return 0;
}

#include <iostream>
