struct Node { int val; Node* next; Node(int v): val(v), next(nullptr) {} };

Node* dedup(Node* head) {
  bool seen[10001] = {false};      // 值绝对值上限约定 10000
  Node* pre = head;
  Node* cur = head ? head->next : nullptr;
  if (head) seen[abs(head->val)] = true;   // 头节点一定保留
  while (cur) {
    int a = abs(cur->val);
    if (seen[a]) {                 // 绝对值重复：摘掉 cur
      pre->next = cur->next;
      Node* tmp = cur; cur = cur->next; delete tmp;
    } else {                       // 首次出现：标记并前进
      seen[a] = true; pre = cur; cur = cur->next;
    }
  }
  return head;
}

int main() {
  int n;
  cin >> n;                        // 第一行：节点个数
  Node* head = nullptr;
  Node* tail = nullptr;
  for (int i = 0; i < n; i++) {    // 第二行起：依次建链（尾插保持原序）
    int v; cin >> v;
    Node* node = new Node(v);
    if (!head) { head = tail = node; }
    else { tail->next = node; tail = node; }
  }
  head = dedup(head);
  bool first = true;
  for (Node* p = head; p; p = p->next) {   // 顺序打印去重后的链表
    if (!first) cout << ' ';
    cout << p->val;
    first = false;
  }
  cout << endl;
  while (head) { Node* t = head; head = head->next; delete t; }  // 释放
  return 0;
}

