vector<int> topo(int num, vector<pair<int,int>>& pre) {
  vector<vector<int>> g(num);
  vector<int> indeg(num, 0);
  for (auto& [a, b] : pre) { g[b].push_back(a); indeg[a]++; } // b 是 a 的先修
  queue<int> q;
  for (int i = 0; i < num; i++) if (indeg[i] == 0) q.push(i);
  vector<int> order;
  while (!q.empty()) {
    int u = q.front(); q.pop();
    order.push_back(u);
    for (int v : g[u]) if (--indeg[v] == 0) q.push(v);
  }
  if ((int)order.size() != num) return {};   // 有环，无法修完
  return order;
}

int main() {
  int num, m; cin >> num >> m;
  vector<pair<int,int>> pre(m);
  for (auto& [a, b] : pre) cin >> a >> b;
  auto ans = topo(num, pre);
  if (ans.empty()) cout << "IMPOSSIBLE" << endl;
  else { for (int i = 0; i < num; i++) cout << ans[i] << (i+1<num?' ':'\n'); }
  return 0;
}

