// 运算符优先级：数字越大越先算
int prec(char c) {
  if (c == '+' || c == '-') return 1;
  if (c == '*' || c == '/') return 2;
  return 0;                     // '(' 的优先级最低，保证不会被弹出
}

// 弹出一个运算符，从 num 栈取两个操作数计算后压回
void apply(stack<long long> &num, char op) {
  long long b = num.top(); num.pop();   // 注意顺序：先弹出的是右操作数
  long long a = num.top(); num.pop();
  long long r = 0;
  if (op == '+') r = a + b;
  else if (op == '-') r = a - b;
  else if (op == '*') r = a * b;
  else r = a / b;                        // 题目保证除数非 0
  num.push(r);
}

int main() {
  string s;
  getline(cin, s);
  stack<long long> num;
  stack<char> op;
  for (size_t i = 0; i < s.size(); i++) {
    char c = s[i];
    if (isdigit(c)) {                    // 扫描完整的多位数
      long long v = 0;
      while (i < s.size() && isdigit(s[i])) v = v * 10 + (s[i++] - '0');
      i--;
      num.push(v);
    } else if (c == '(') {
      op.push(c);
    } else if (c == ')') {
      while (!op.empty() && op.top() != '(') { apply(num, op.top()); op.pop(); }
      op.pop();                           // 丢掉 '('
    } else {                              // + - * /
      // 先算掉所有优先级不低于当前的运算符 -> 保证同级左结合
      while (!op.empty() && prec(op.top()) >= prec(c)) { apply(num, op.top()); op.pop(); }
      op.push(c);
    }
  }
  while (!op.empty()) { apply(num, op.top()); op.pop(); }
  cout << num.top() << endl;
  return 0;
}

