using namespace std;

vector<int> parent_, sz;

int find(int x) {
  if (parent_[x] != x) parent_[x] = find(parent_[x]);   // 路径压缩
  return parent_[x];
}

void unite(int a, int b) {
  int ra = find(a), rb = find(b);
  if (ra == rb) return;                 // 已在同一集合，幂等
  if (sz[ra] < sz[rb]) swap(ra, rb);    // 小树挂到大树上（按大小合并）
  parent_[rb] = ra;
  sz[ra] += sz[rb];
}

int main() {
  int n, m;
  cin >> n >> m;
  parent_.resize(n + 1);
  sz.assign(n + 1, 1);
  for (int i = 1; i <= n; i++) parent_[i] = i;

  for (int i = 0; i < m; i++) {
    int a, b;
    cin >> a >> b;
    unite(a, b);
  }

  int groups = 0;
  for (int i = 1; i <= n; i++)
    if (find(i) == i) groups++;         // 根的个数 = 连通分量数
  cout << groups << endl;
  return 0;
}

