typedef pair<long long, int> pli;         // (距离, 节点)

int main() {
  int n, m, s, t;
  cin >> n >> m >> s >> t;
  vector<vector<pair<int, int>>> g(n + 1);   // 邻接表：{邻居, 权}
  for (int i = 0; i < m; i++) {
    int u, v, w;
    cin >> u >> v >> w;
    g[u].push_back({v, w});
    g[v].push_back({u, w});                  // 无向图；有向图删掉这一行
  }

  const long long INF = LLONG_MAX / 4;
  vector<long long> dist(n + 1, INF);
  vector<long long> cnt(n + 1, 0);            // 最短路径条数
  priority_queue<pli, vector<pli>, greater<pli>> pq;

  dist[s] = 0;
  cnt[s] = 1;                                 // 起点到自己算 1 条
  pq.push({0, s});
  while (!pq.empty()) {
    pli cur = pq.top(); pq.pop();
    long long d = cur.first;
    int u = cur.second;
    if (d > dist[u]) continue;                // 过期堆项，跳过（关键：避免重复计数）
    for (auto &e : g[u]) {
      int v = e.first, w = e.second;
      long long nd = d + w;
      if (nd < dist[v]) {
        dist[v] = nd;
        cnt[v] = cnt[u];                      // 更短 -> 覆盖计数
        pq.push({nd, v});
      } else if (nd == dist[v]) {
        cnt[v] += cnt[u];                     // 等长 -> 累加计数
      }
    }
  }
  if (dist[t] >= INF) cout << -1 << " " << 0 << endl;
  else cout << dist[t] << " " << cnt[t] << endl;
  return 0;
}

#include <iostream>
#include <list>
#include <unordered_map>
#include <string>
using namespace std;

struct LRU {
  int cap;
  list<pair<int, int>> lst;                                  // 头部最新，尾部最旧
  unordered_map<int, list<pair<int, int>>::iterator> pos;    // key -> 链表迭代器

  explicit LRU(int c) : cap(c) {}

  int get(int key) {
    auto it = pos.find(key);
    if (it == pos.end()) return -1;          // 未命中
    lst.splice(lst.begin(), lst, it->second); // 提到表头（O(1)，不搬数据）
    return it->second->second;
  }

  void put(int key, int val) {
    auto it = pos.find(key);
    if (it != pos.end()) {                   // 已存在：更新 + 提头
      it->second->second = val;
      lst.splice(lst.begin(), lst, it->second);
      return;
    }
    if ((int)lst.size() == cap) {            // 满：淘汰最久未用
      int oldKey = lst.back().first;
      lst.pop_back();
      pos.erase(oldKey);                     // 两处结构必须同步删，否则内存泄漏 + 脏命中
    }
    lst.push_front({key, val});
    pos[key] = lst.begin();
  }
};

int main() {
  int cap;
  cin >> cap;
  LRU cache(cap);
  string op;
  while (cin >> op) {
    if (op == "get") {
      int k; cin >> k;
      cout << cache.get(k) << endl;
    } else if (op == "put") {
      int k, v; cin >> k >> v;
      cache.put(k, v);
    }
  }
  return 0;
}

