// 计算 (a^b) % m，b 可到 1e18
long long power_mod(long long a, long long b, long long m) {
  if (m == 1) return 0;              // 任何数 mod 1 都是 0
  long long res = 1 % m;
  a %= m;                            // 先约简底数
  while (b > 0) {
    if (b & 1) res = (__int128)res * a % m;   // 当前位为 1：乘进答案（__int128 防溢出）
    a = (__int128)a * a % m;                  // 底数平方
    b >>= 1;                                  // 指数右移
  }
  return res;
}

int main() {
  long long a, b, m;
  cin >> a >> b >> m;
  cout << power_mod(a, b, m) << endl;
  return 0;
}

