struct Node {
  int val;
  Node *l, *r;
  explicit Node(int v) : val(v), l(nullptr), r(nullptr) {}
};

// 按前序读入建树，'#' 表示空
Node *build() {
  string s;
  if (!(cin >> s)) return nullptr;
  if (s == "#") return nullptr;
  Node *p = new Node(stoi(s));
  p->l = build();
  p->r = build();
  return p;
}

int main() {
  Node *root = build();
  if (!root) return 0;

  queue<Node *> q;
  q.push(root);
  int level = 0;
  while (!q.empty()) {
    int sz = q.size();                 // 当前层节点数必须在出队前记下来
    vector<int> row;
    for (int i = 0; i < sz; i++) {
      Node *p = q.front(); q.pop();
      row.push_back(p->val);
      if (p->l) q.push(p->l);
      if (p->r) q.push(p->r);
    }
    if (level % 2 == 1) reverse(row.begin(), row.end());   // 奇数层换向
    for (size_t i = 0; i < row.size(); i++) {
      if (i) cout << ' ';
      cout << row[i];
    }
    cout << endl;
    level++;
  }
  return 0;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

// 求 next 数组：next[i] = pattern[0..i] 的最长相等真前后缀长度
vector<int> buildNext(const string &p) {
  int m = (int)p.size();
  vector<int> nxt(m, 0);
  int j = 0;                              // j = 当前已匹配的前缀长度
  for (int i = 1; i < m; i++) {
    while (j > 0 && p[i] != p[j]) j = nxt[j - 1];  // 失配：沿 next 回退
    if (p[i] == p[j]) j++;                // 匹配：前缀长度 +1
    nxt[i] = j;
  }
  return nxt;
}

int main() {
  string text, pat;
  getline(cin, text);
  getline(cin, pat);
  if (pat.empty()) return 0;

  vector<int> nxt = buildNext(pat);
  vector<int> hits;                       // 所有出现位置（0 基）
  int j = 0;                              // 文本指针 i 只前进，不回退
  for (int i = 0; i < (int)text.size(); i++) {
    while (j > 0 && text[i] != pat[j]) j = nxt[j - 1];
    if (text[i] == pat[j]) j++;
    if (j == (int)pat.size()) {
      hits.push_back(i - j + 1);          // 命中：起点 = 终点 - 长度 + 1
      j = nxt[j - 1];                     // 假装失配，继续找重叠出现
    }
  }

  cout << hits.size() << endl;
  for (size_t k = 0; k < hits.size(); k++) {
    if (k) cout << ' ';
    cout << hits[k];
  }
  if (!hits.empty()) cout << endl;
  return 0;
}

#include <iostream>
#include <vector>
using namespace std;

long long mergeCount(vector<int> &a, vector<int> &tmp, int l, int r) {
  if (l >= r) return 0;
  int mid = (l + r) / 2;
  long long cnt = 0;
  cnt += mergeCount(a, tmp, l, mid);         // 左半内部逆序对
  cnt += mergeCount(a, tmp, mid + 1, r);     // 右半内部逆序对

  int i = l, j = mid + 1, k = l;
  while (i <= mid && j <= r) {
    if (a[i] <= a[j]) {
      tmp[k++] = a[i++];                     // 不产生逆序
    } else {
      cnt += mid - i + 1;                    // 批量累加：a[i..mid] 全大于 a[j]
      tmp[k++] = a[j++];
    }
  }
  while (i <= mid) tmp[k++] = a[i++];        // 左段剩余
  while (j <= r) tmp[k++] = a[j++];          // 右段剩余
  for (int t = l; t <= r; t++) a[t] = tmp[t];// 写回，供上层使用
  return cnt;
}

int main() {
  int n;
  cin >> n;
  vector<int> a(n), tmp(n);
  for (int i = 0; i < n; i++) cin >> a[i];
  cout << mergeCount(a, tmp, 0, n - 1) << endl;
  return 0;
}

#include <iostream>
#include <deque>
#include <vector>
using namespace std;

int main() {
  int n, k;
  cin >> n >> k;
  vector<int> a(n);
  for (int i = 0; i < n; i++) cin >> a[i];

  deque<int> dq;            // 存下标，对应值单调递增
  vector<int> ans;
  for (int i = 0; i < n; i++) {
    // 1) 队尾比当前大的全部出队：它们永远不可能再成为最小值
    while (!dq.empty() && a[dq.back()] >= a[i]) dq.pop_back();
    dq.push_back(i);

    // 2) 队头若已滑出窗口左边界则弹出（按下标判断，不能用值判断）
    if (dq.front() <= i - k) dq.pop_front();

    // 3) 窗口填满后即可输出
    if (i >= k - 1) ans.push_back(a[dq.front()]);
  }

  for (size_t i = 0; i < ans.size(); i++) {
    if (i) cout << ' ';
    cout << ans[i];
  }
  cout << endl;
  return 0;
}

