  while (l <= r) {
    int mid = l + (r - l) / 2;              // 防溢出写法
    if (a[mid] == target) return mid;

    if (a[l] <= a[mid]) {                   // 左半 [l, mid] 有序
      if (a[l] <= target && target < a[mid]) r = mid - 1;  // target 落在左半
      else l = mid + 1;
    } else {                                // 右半 [mid, r] 有序
      if (a[mid] < target && target <= a[r]) l = mid + 1;  // target 落在右半
      else r = mid - 1;
    }
  }
  return -1;                                // 未找到
}

