// 闰年判定：能被 400 整除，或能被 4 整除但不能被 100 整除
bool isLeap(int y) { return (y % 400 == 0) || (y % 4 == 0 && y % 100 != 0); }

// 把日期折算成「距 1970-01-01 的天数」，从而跨年跨闰年都能直接相减
long long daysFromEpoch(int y, int m, int d) {
  static const int mdays[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
  long long days = 0;
  for (int i = 1970; i < y; i++) days += isLeap(i) ? 366 : 365;   // 整年
  for (int i = 1; i < m; i++) {                                   // 整月
    days += mdays[i];
    if (i == 2 && isLeap(y)) days += 1;                           // 闰年 2 月多一天
  }
  days += d - 1;                                                  // 当月零头（当天未过完）
  return days;
}

